    Bug 1839280 - Add additional logging of XulStore values. r=mkmelin

    Clearing the XulStore once per test helped already to reduce test fails, but here
    it seems the test opens multiple message windows and dies for the same reason at
    some point. The additional logging should provide more details when and why the
    bad resize happens.

    Differential Revision: https://phabricator.services.mozilla.com/D276145

diff --git a/mail/components/extensions/test/browser/head.js b/mail/components/extensions/test/browser/head.js
index 885e63eceb5..242e285d2ff 100644
--- a/mail/components/extensions/test/browser/head.js
+++ b/mail/components/extensions/test/browser/head.js
@@ -52,6 +52,8 @@ requestLongerTimeout = factor => {
 };
 requestLongerTimeout(1);

+let openedMsgWindowCount = 0;
+
 add_setup(async () => {
   await check3PaneState(true, true);
   const tabmail = document.getElementById("tabmail");
@@ -513,6 +515,23 @@ async function openMessageInWindow(msgHdr) {
     throw new Error("No message passed to openMessageInWindow");
   }

+  // Temporary logging
+  dump(
+    ` ---- A - ${openedMsgWindowCount} ${JSON.stringify(
+      ["chrome://messenger/content/messageWindow.xhtml"].map(url =>
+        Array.from(Services.xulStore.getIDsEnumerator(url)).map(id => ({
+          [id]: Array.from(
+            Services.xulStore.getAttributeEnumerator(url, id)
+          ).map(attr => ({
+            [attr]: Services.xulStore.getValue(url, id, attr),
+          })),
+        }))
+      ),
+      null,
+      2
+    )}`
+  );
+
   const messageWindowPromise = BrowserTestUtils.domWindowOpenedAndLoaded(
     undefined,
     async win =>
@@ -523,6 +542,25 @@ async function openMessageInWindow(msgHdr) {

   const messageWindow = await messageWindowPromise;
   await BrowserTestUtils.waitForEvent(messageWindow, "MsgLoaded");
+  openedMsgWindowCount++;
+
+  // Temporary logging
+  dump(
+    ` ---- B - ${openedMsgWindowCount} ${JSON.stringify(
+      ["chrome://messenger/content/messageWindow.xhtml"].map(url =>
+        Array.from(Services.xulStore.getIDsEnumerator(url)).map(id => ({
+          [id]: Array.from(
+            Services.xulStore.getAttributeEnumerator(url, id)
+          ).map(attr => ({
+            [attr]: Services.xulStore.getValue(url, id, attr),
+          })),
+        }))
+      ),
+      null,
+      2
+    )}`
+  );
+
   return messageWindow;
 }
